<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Alberto Watches | Admin</title>
<link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css" rel="stylesheet"><style>
:root{--bg:#101a15;--panel:#1b2b21;--gold:#d6b77e;--muted:#9eaa9f}*{box-sizing:border-box}body{margin:0;background:#101a15;color:#f5f2e9;font-family:Arial,sans-serif}.sidebar{width:245px;position:fixed;inset:0 auto 0 0;background:#142119;border-right:1px solid #354638;padding:26px 18px}.brand{font:22px Georgia;color:var(--gold);letter-spacing:2px}.brand small{display:block;font:9px Arial;letter-spacing:3px;color:#b3bcb2}.nav-btn{display:block;width:100%;text-align:left;margin-top:8px;padding:12px 14px;border:0;background:transparent;color:#bdc7bd;border-radius:4px}.nav-btn.active,.nav-btn:hover{background:#2a3d30;color:var(--gold)}.main{margin-left:245px;padding:30px;max-width:1500px}.top{display:flex;justify-content:space-between;align-items:center;margin-bottom:25px}.top h1{font:34px Georgia}.muted{color:var(--muted)}.stat{background:var(--panel);border:1px solid #394c3e;padding:22px;border-radius:8px}.stat small{color:var(--muted)}.stat strong{display:block;font:30px Georgia;color:var(--gold);margin-top:8px}.panel{background:var(--panel);border:1px solid #394c3e;padding:20px;border-radius:8px}.table{color:#f4f2e9;--bs-table-bg:transparent;--bs-table-color:#f4f2e9;--bs-table-border-color:#3b4d40}.table th{color:var(--gold);font-size:11px;text-transform:uppercase;letter-spacing:1px}.form-control,.form-select{background:#101a15;border:1px solid #506052;color:white;border-radius:3px}.form-control:focus,.form-select:focus{background:#101a15;color:white;border-color:var(--gold);box-shadow:none}.btn-gold{background:var(--gold);color:#111;border:0;border-radius:3px}.btn-outline-gold{border:1px solid var(--gold);color:var(--gold)}.badge-status{background:#3a4c3d;color:#e7d1a4;padding:5px 8px;border-radius:3px}.login-wrap{max-width:420px;margin:10vh auto;padding:28px;background:var(--panel);border:1px solid var(--gold)}.login-wrap h1{font:32px Georgia}.content-section{display:none}.content-section.active{display:block}.table-responsive{overflow-x:auto}.message-text{max-width:420px;white-space:normal;overflow-wrap:anywhere}.admin-note{font-size:12px;color:var(--muted)}@media(max-width:800px){.sidebar{position:static;width:auto;padding:15px}.sidebar nav{display:flex;overflow:auto}.nav-btn{white-space:nowrap;width:auto;margin:4px}.main{margin:0;padding:18px}.brand{font-size:18px}.top h1{font-size:26px}}
</style></head><body>
<div id="loginScreen" class="login-wrap"><p class="brand">ALBERTO <small>ADMINISTRATION</small></p><h1 class="mt-4">Admin <span style="color:var(--gold)">login.</span></h1><p class="muted">Sign in to manage your watch store.</p><form id="adminLogin"><label class="form-label mt-3">Email</label><input class="form-control" id="adminEmail" type="email" required><label class="form-label mt-3">Password</label><input class="form-control" id="adminPassword" type="password" required><button class="btn btn-gold w-100 mt-4 py-2">Login to dashboard</button><p id="loginError" class="text-warning small mt-3"></p></form><p class="admin-note mt-3">First time? <a href="setup.php" style="color:var(--gold)">Create your admin account</a></p><a href="../index.html" class="admin-note">← Back to website</a></div>
<div id="adminApp" hidden>
<aside class="sidebar"><p class="brand">ALBERTO <small>WATCH COMPANY</small></p><p class="muted small mt-4 mb-2">MANAGEMENT</p><nav>
<button class="nav-btn active" data-view="dashboard"><i class="bi bi-grid me-2"></i>Dashboard</button>
<button class="nav-btn" data-view="orders"><i class="bi bi-bag-check me-2"></i>Orders</button>
<button class="nav-btn" data-view="messages"><i class="bi bi-envelope me-2"></i>Messages</button>
<button class="nav-btn" data-view="products"><i class="bi bi-watch me-2"></i>Products</button>
<button class="nav-btn" data-view="customers"><i class="bi bi-people me-2"></i>Customers</button>
</nav><button id="adminLogout" class="nav-btn mt-5"><i class="bi bi-box-arrow-left me-2"></i>Logout</button><a href="../index.html" class="nav-btn text-decoration-none"><i class="bi bi-shop me-2"></i>View website</a></aside>
<main class="main"><div class="top"><div><p class="muted small mb-1">ALBERTO WATCH COMPANY / ADMIN</p><h1 id="viewTitle">Dashboard</h1></div><span class="muted" id="adminIdentity"></span></div>
<section id="view-dashboard" class="content-section active"><div class="row g-3" id="stats"></div><div class="panel mt-4"><h4>Welcome to your store dashboard</h4><p class="muted mb-0">Review customer orders, read footer enquiries, update product listings and manage your customers from here.</p></div></section>
<section id="view-orders" class="content-section"><div class="panel"><h4>Customer orders</h4><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Order</th><th>Customer</th><th>Items</th><th>Total</th><th>Delivery</th><th>Status</th><th>Update</th></tr></thead><tbody id="ordersTable"></tbody></table></div></div></section>
<section id="view-messages" class="content-section"><div class="panel"><h4>Website enquiries</h4><p class="muted small">Messages submitted through the footer contact form appear here.</p><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Received</th><th>Sender</th><th>Message</th><th>Status</th><th>Update</th></tr></thead><tbody id="messagesTable"></tbody></table></div></div></section>
<section id="view-products" class="content-section"><div class="panel"><div class="d-flex justify-content-between align-items-center flex-wrap gap-2"><div><h4>Products</h4><p class="muted small mb-0">Changes are saved to data/products.json.</p></div><button class="btn btn-gold" id="addProduct">+ Add product</button></div><div class="table-responsive mt-3"><table class="table align-middle"><thead><tr><th>Product</th><th>Category</th><th>Reference</th><th>Price</th><th>Actions</th></tr></thead><tbody id="productsTable"></tbody></table></div></div></section>
<section id="view-customers" class="content-section"><div class="panel"><h4>Registered customers</h4><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Name</th><th>Email</th><th>Joined</th></tr></thead><tbody id="customersTable"></tbody></table></div></div></section>
</main></div>
<div class="modal fade" id="productEditor" tabindex="-1"><div class="modal-dialog modal-lg modal-dialog-centered"><div class="modal-content" style="background:#1b2b21;color:white;border:1px solid var(--gold)"><div class="modal-header border-secondary"><h5 id="productEditorTitle">Add product</h5><button class="btn-close btn-close-white" data-bs-dismiss="modal"></button></div><form id="productForm"><div class="modal-body"><input type="hidden" id="pId"><div class="row g-3">
<div class="col-md-6"><label class="form-label">Product name</label><input class="form-control" id="pName" required></div><div class="col-md-6"><label class="form-label">Brand</label><input class="form-control" id="pBrand" required></div>
<div class="col-md-4"><label class="form-label">Category</label><select class="form-select" id="pCategory"><option value="luxury">Luxury</option><option value="vintage">Vintage</option><option value="smart">Smart</option><option value="classic">Classic</option><option value="clocks">Clocks</option></select></div><div class="col-md-4"><label class="form-label">Price (USD)</label><input class="form-control" id="pPrice" type="number" min="0.01" step="0.01" required></div><div class="col-md-4"><label class="form-label">Reference</label><input class="form-control" id="pRef"></div>
<div class="col-12"><label class="form-label">Image URL (https://...)</label><input class="form-control" id="pImage" type="url" required></div><div class="col-12"><label class="form-label">Description</label><textarea class="form-control" id="pDescription" rows="2"></textarea></div>
<div class="col-md-4"><label class="form-label">Tag</label><input class="form-control" id="pTag"></div><div class="col-md-4"><label class="form-label">Movement</label><input class="form-control" id="pMovement"></div><div class="col-md-4"><label class="form-label">Case</label><input class="form-control" id="pCase"></div><div class="col-md-4"><label class="form-label">Water resistance</label><input class="form-control" id="pWater"></div></div></div><div class="modal-footer border-secondary"><button class="btn btn-gold">Save product</button></div></form></div></div></div>
<script src="https://code.jquery.com/jquery-3.7.1.min.js"></script><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script><script src="admin.js"></script></body></html>
